using UnityEditor;
using UnityEngine;
using System;
public static class VerifyLixinVfx {
  public static string Run() {
    var t = Type.GetType("JojoP.Gameplay.Brothers.SkillVfx, JojoP.HotUpdate");
    string[] keys = {"fx_lixin_gamble","fx_lixin_crunch","fx_lixin_overwork","fx_buff_atk"};
    var sb = new System.Text.StringBuilder();
    sb.Append("SkillVfx=").Append(t != null ? "ok" : "MISSING").Append(';');
    foreach (var k in keys) {
      var p = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Bundle/Vfx/"+k+".prefab");
      var ps = p != null ? p.GetComponent<ParticleSystem>() : null;
      var r = p != null ? p.GetComponent<ParticleSystemRenderer>() : null;
      sb.Append(k).Append(p==null?" miss":(" mesh="+(r!=null&&r.mesh!=null)+" mat="+(r!=null&&r.sharedMaterial!=null)+" burst="+(ps!=null))).Append(';');
    }
    return sb.ToString();
  }
}
